import re
import sys

values = {}
assignment = re.compile(
    r"\b(a|b|c|d|TMP)\s*<-\s*(\d+|\(\s*(a|b|c|d|TMP)\s*([+-])\s*(\d+)\s*\)\s*mod\s*100)\s*;"
)

for line in sys.stdin:
    line = line.split("//", 1)[0]
    for match in assignment.finditer(line):
        target, expression, source, operator, operand = match.groups()
        if source is None:
            values[target] = int(expression)
        else:
            delta = int(operand)
            if operator == "-":
                delta = -delta
            values[target] = (values[source] + delta) % 100

print(
    f"a ?= {values['a']}; b ?= {values['b']}; "
    f"c ?= {values['c']}; d ?= {values['d']}; TMP ?= {values['TMP']};"
)
